window.VN_LEARNING=window.VN_LEARNING||{};
window.VN_LEARNING["lesson-8"]={
  version:2,title:"Designing a Vegetarian Diet",chapter:8,duration:"105–125 minutes",
  outcomes:["Build a nutrient-dense vegetarian pattern without relying on an obsolete food-guide graphic.","Use food-group roles and meal anchors to cover energy, protein, iron, calcium, B12 and essential fats.","Compare plant beverages and meat or cheese alternatives by label rather than category name.","Distinguish whole fruit from juice while respecting culture and accessibility.","Describe a macrobiotic dietary pattern without treating it as nutritionally equivalent to a well-planned vegetarian diet.","Screen highly restrictive patterns for energy, protein, B12, D, calcium, iron, iodine, zinc and omega-3 risk.","Create a practical day pattern that is flexible, enjoyable and appropriate to individual needs."],
  modules:[
    {id:"pattern",title:"Design the pattern before counting details",summary:"Start with adequacy, variety, pattern quality and eating context rather than one historic serving chart.",moments:[
      {id:"l8-m1",title:"Vegetarian describes an exclusion, not a complete diet",highYield:"A sound pattern still needs adequate energy, protein-rich foods, produce, grains or starchy foods, fats and deliberate fortified sources.",teaching:["Vegetarian patterns range from lacto-ovo diets to vegan diets and many culturally specific variations. The label tells you something about foods excluded, but not whether the person eats enough, includes legumes, chooses whole grains, uses fortified foods or has reliable B12.","Modern planning emphasizes proportions and food quality rather than treating a 1940s allowance or a single vegetarian food pyramid as timeless. A useful structure includes protein-rich plant foods, vegetables and fruit, whole or enriched grains and starchy foods, nuts/seeds or other unsaturated fats, and nutrient-specific fortified foods or supplements."],keyPoints:["Vegetarian patterns are diverse.","Diet identity does not prove adequacy.","Energy sufficiency comes before fine-tuning.","Fortified sources address predictable gaps."],visual:{title:"Vegetarian pattern foundation",kind:"layers",items:[{label:"Enough",detail:"Energy and food access"},{label:"Anchor",detail:"Legumes, soy foods, eggs/dairy if used"},{label:"Build",detail:"Grains/starches, vegetables and fruit"},{label:"Enrich",detail:"Nuts, seeds and unsaturated fats"},{label:"Secure",detail:"Reliable B12 and other assessed nutrients"}]},mnemonic:{title:"E-A-B-E-S",cue:"Enough · Anchor · Build · Enrich · Secure",explanation:"A pattern sequence, not a rigid plate rule."},goodToKnow:"A highly processed vegetarian pattern can still be high in sodium, saturated fat, refined starch or added sugar.",practiceConnection:"Ask what a usual week looks like, not whether the client can recite a food guide.",activity:{prompt:"What does the label vegetarian establish by itself?",options:[{text:"Which animal foods are excluded or included, but not overall adequacy",correct:true,feedback:"Correct. Quality, quantity and fortified sources still need assessment."},{text:"That every nutrient target is met",correct:false,feedback:"The label does not establish intake or bioavailability."},{text:"That all foods are minimally processed",correct:false,feedback:"Vegetarian foods span the full processing spectrum."}]}} ,
      {id:"l8-m2",title:"Variety is functional, not decorative",highYield:"Different food families cover different nutrient jobs; rotating them builds redundancy and resilience.",teaching:["Legumes and soy foods contribute protein, iron, zinc and fibre. Whole and enriched grains provide energy, protein and several B vitamins. Vegetables and fruit contribute vitamin C, folate, carotenoids and potassium. Nuts and seeds add energy, protein, vitamin E, minerals and essential fats.","Variety does not require a different ingredient at every meal or imported superfoods. It can mean rotating lentils, chickpeas, tofu and peanut butter across a week; using several grains or starchy staples; and choosing produce of different types and colours. Cultural foods can meet these roles without being forced into one Western menu."],keyPoints:["Food families have overlapping but distinct roles.","Rotation supports redundancy.","Cultural staples belong in the plan.","Variety is assessed over time."],visual:{title:"Food-family roles",kind:"map",items:[{label:"Legumes/soy",detail:"Protein, iron, zinc, fibre"},{label:"Grains/starches",detail:"Energy, protein and B vitamins"},{label:"Vegetables/fruit",detail:"Vitamin C, folate, carotenoids, potassium"},{label:"Nuts/seeds",detail:"Energy, fats, protein and minerals"},{label:"Fortified foods",detail:"Strategic B12, calcium, D and iodine where applicable"}]},mnemonic:{title:"LGVNF",cue:"Legumes · Grains · Vegetables/fruit · Nuts/seeds · Fortified",explanation:"Check the five roles across the day or week."},goodToKnow:"Refined grains can have cultural and practical value; pair them within an overall pattern rather than labelling them morally bad.",practiceConnection:"A pattern must fit budget, cooking access, food traditions, sensory preferences and time.",activity:{prompt:"Which change most directly increases nutrient redundancy?",options:[{text:"Rotate several legumes, grains, produce types and nuts/seeds across the week",correct:true,feedback:"Correct. Rotation provides overlapping sources."},{text:"Eat one fortified snack as the entire diet",correct:false,feedback:"One product cannot replace a varied pattern."},{text:"Remove all cultural staple foods",correct:false,feedback:"Staples can be valuable energy and nutrient sources."}]}}
    ]},
    {id:"anchors",title:"Anchor meals with protein, minerals and essential fats",summary:"Use repeatable building blocks instead of chasing one perfect food.",moments:[
      {id:"l8-m3",title:"A protein anchor turns sides into a meal",highYield:"Include a meaningful protein-rich food at meals; complementary proteins do not need to be paired at the same sitting.",teaching:["Legumes, tofu, tempeh, textured vegetable protein, seitan, soy or pea beverages, eggs and dairy when used, and selected meat alternatives can anchor a meal. Nuts and seeds contribute protein but may need larger portions or another anchor when protein needs are high.","Plant foods provide all essential amino acids in different proportions. Adequate energy, total protein and variety across the day are the priorities for most healthy people. Older rules that require rice and beans to be eaten together at every meal create unnecessary complexity."],keyPoints:["Use a clear protein anchor at meals.","Total intake and energy adequacy matter.","Variety across the day supplies amino acids.","Same-meal combining is not required."],visual:{title:"Meal anchor examples",kind:"comparison",items:[{label:"Breakfast",detail:"Fortified soy beverage plus oats, nuts and fruit"},{label:"Lunch",detail:"Lentil bowl or hummus wrap"},{label:"Dinner",detail:"Tofu, tempeh, beans or seitan with grain/starch and vegetables"},{label:"Snack",detail:"Soy yogurt, roasted chickpeas or nut/seed spread"}]},mnemonic:{title:"Find the anchor",cue:"What is the protein-rich centre?",explanation:"Ask this before adding supplements or counting minor grams."},goodToKnow:"Plant beverage protein varies greatly; soy and pea products commonly provide more than almond, cashew or many oat beverages.",practiceConnection:"For older adults, athletes or low appetites, distribute adequate high-quality protein across eating occasions.",activity:{prompt:"Which statement about protein combining is current?",options:[{text:"Varied plant proteins can complement one another across the day",correct:true,feedback:"Correct. Same-meal pairing is not required for most people."},{text:"Every meal must pair two specific plant proteins",correct:false,feedback:"That older rule is unnecessarily rigid."},{text:"Plant foods contain no essential amino acids",correct:false,feedback:"They contain all essential amino acids in varying proportions."}]}} ,
      {id:"l8-m4",title:"Essential fats need a daily route",highYield:"Use regular ALA-rich foods and consider algal EPA/DHA individually instead of chasing an ideal omega ratio.",teaching:["Alpha-linolenic acid, or ALA, is the essential plant omega-3 fat. Ground flax, chia, hemp, walnuts and canola or soybean oil are practical sources. Whole seeds may pass through less digested, so grinding flax improves access.","The body converts some ALA to EPA and DHA, but conversion is limited and variable. Algal EPA/DHA provides a direct vegetarian source and may be considered for pregnancy, lactation or individual clinical circumstances with qualified guidance. Current teaching should not make a single omega-6-to-omega-3 ratio the goal."],keyPoints:["ALA is essential.","Flax, chia, hemp and walnuts supply ALA.","Conversion to EPA/DHA is limited and variable.","Algal EPA/DHA is a direct vegetarian option."],visual:{title:"Omega-3 route",kind:"flow",items:[{label:"Food",detail:"Flax, chia, hemp, walnuts or selected oils"},{label:"ALA",detail:"Essential dietary omega-3"},{label:"Conversion",detail:"Limited and variable formation of EPA/DHA"},{label:"Direct option",detail:"Algal EPA/DHA when individually indicated"}]},mnemonic:{title:"FCHW",cue:"Flax · Chia · Hemp · Walnuts",explanation:"Four repeatable ALA foods."},goodToKnow:"Sea vegetables are not dependable direct sources of EPA and DHA; microalgae-derived oils are the measured option.",practiceConnection:"Ask about pregnancy, medications, bleeding risk and supplement dose before recommending concentrated omega-3 products.",activity:{prompt:"Which food is a concentrated ALA source?",options:[{text:"Ground flaxseed",correct:true,feedback:"Correct. Ground flax provides accessible ALA."},{text:"Beet sugar",correct:false,feedback:"Sugar is not an omega-3 source."},{text:"Unfortified rice milk",correct:false,feedback:"It is not a concentrated ALA source."}]}}
    ]},
    {id:"labels",title:"Read products, not category names",summary:"Plant beverages, cheeses, meat alternatives, yeast and juices vary too much for blanket claims.",moments:[
      {id:"l8-m5",title:"Plant beverage is a category, not a nutrient profile",highYield:"Protein, calcium, vitamin D, B12, iodine, sugar and energy vary by product and country; check the label every time.",teaching:["Soy and pea beverages commonly provide protein amounts closer to cow's milk, while many almond, cashew, coconut, rice and oat beverages contain much less. Fortification with calcium, vitamin D and B12 varies. Organic products may follow different fortification rules in some jurisdictions.","For a product used as a major milk replacement, compare serving size, protein, calcium, vitamin D, B12, added sugar and, where listed, iodine. Shake calcium-fortified beverages because added minerals can settle. Infants require breast milk or suitable commercial infant formula—not ordinary plant beverage."],keyPoints:["Protein varies sharply across plant beverages.","Fortification is not universal.","Added minerals can settle.","Plant beverage is not infant formula."],visual:{title:"Plant beverage label scan",kind:"sequence",items:[{label:"Serving",detail:"Compare the same volume"},{label:"Protein",detail:"Is it a meaningful amount?"},{label:"Fortification",detail:"Calcium, D and B12"},{label:"Sugar",detail:"Added versus intrinsic carbohydrate"},{label:"Use case",detail:"Adult beverage, cooking ingredient or unsuitable infant replacement"}]},mnemonic:{title:"SPFSU",cue:"Serving · Protein · Fortification · Sugar · Use",explanation:"A five-step carton check."},goodToKnow:"Calcium may appear on the label but remain in sediment if the beverage is not shaken.",practiceConnection:"Document the exact brand and product because formulations change.",activity:{prompt:"Which plant beverages are commonly highest in protein?",options:[{text:"Soy and pea beverages",correct:true,feedback:"Correct. Many provide substantially more protein than almond or rice beverages."},{text:"All plant beverages equally",correct:false,feedback:"Protein and fortification vary widely."},{text:"Only coconut water",correct:false,feedback:"Coconut water is not a high-protein milk replacement."}]}} ,
      {id:"l8-m6",title:"Alternative products can help, but their roles differ",highYield:"A vegetarian cheese or meat analogue counts only for the nutrients it actually contains.",teaching:["Some meat alternatives are protein-rich and fortified with iron, zinc or B12; others are primarily starch, oil and sodium. Some plant cheeses provide little protein or calcium. Peanut butter, avocado and sour cream may all be energy-dense foods, but they do not perform identical nutrient roles.","Nutritional yeast contains B12 only when fortified. Blackstrap molasses can contribute iron and some calcium, but amounts, serving size and absorption limit its role. Use products as convenient tools within the pattern, not as nutritional equivalents based on appearance or marketing."],keyPoints:["Check protein in meat and cheese alternatives.","Fortification varies by product.","Nutritional yeast is not automatically B12-fortified.","Appearance does not establish equivalence."],visual:{title:"Alternative product roles",kind:"comparison",items:[{label:"Protein analogue",detail:"Tofu, tempeh, seitan or a verified high-protein product"},{label:"Flavour/texture",detail:"Some plant cheeses add taste but little protein"},{label:"Energy/fat",detail:"Avocado, oils, nut and seed spreads"},{label:"Fortified helper",detail:"Products with confirmed B12, calcium, D or iron"}]},mnemonic:{title:"R-L-R",cue:"Role · Label · Replacement",explanation:"Define the role, read the label, then decide what it replaces."},goodToKnow:"A serving category in an old food guide is not a guarantee that every modern analogue has the same composition.",practiceConnection:"Teach label comparison without labelling processed products as universally good or bad; context, access and total pattern matter.",activity:{prompt:"Which statement about plant cheese is accurate?",options:[{text:"Protein and calcium vary, and many products provide little of either",correct:true,feedback:"Correct. The label determines its nutrition role."},{text:"Every plant cheese is nutritionally identical to dairy cheese",correct:false,feedback:"Composition varies substantially."},{text:"All plant cheese contains B12 automatically",correct:false,feedback:"B12 must be confirmed on the label."}]}}
    ]},
    {id:"day-design",title:"Turn evidence into a workable day",summary:"Use flexible meal architecture, whole fruit, culture and access to make the plan sustainable.",moments:[
      {id:"l8-m7",title:"Whole fruit and juice are not interchangeable",highYield:"Whole fruit generally provides more intact fibre and satiety; juice can fit in limited contexts but should not automatically equal fruit.",teaching:["Whole fruit provides water, vitamins, minerals, phytochemicals and a cellular fibre structure that slows eating and supports fullness. Juice removes most fibre and is easier to consume quickly. Fruit drinks may contain little juice and added sugar, so the term drink does not mean a fruit serving.","Juice can be useful when appetite, chewing or energy needs create a specific role, but portion and life stage matter. For infants, routine juice is not needed; pediatric guidance should be followed. Dried fruit is concentrated and can contribute iron and energy, though serving size and dental considerations differ from fresh fruit."],keyPoints:["Whole fruit retains fibre structure.","Juice and fruit drinks differ.","Dried fruit is concentrated.","Context determines whether juice has a role."],visual:{title:"Fruit forms",kind:"comparison",items:[{label:"Whole fruit",detail:"Fibre structure, chewing and satiety"},{label:"100% juice",detail:"Vitamins and carbohydrate with little fibre"},{label:"Fruit drink",detail:"May contain added sugar and limited juice"},{label:"Dried fruit",detail:"Concentrated energy and minerals; smaller portion"}]},mnemonic:{title:"Chew first",cue:"Whole fruit is the default",explanation:"Use juice intentionally rather than assuming equal structure."},goodToKnow:"A product can display fruit imagery while containing mostly water, sweetener and flavouring.",practiceConnection:"Consider dental health, glycemic management, appetite, chewing ability and food access when choosing fruit form.",activity:{prompt:"Why is whole fruit generally preferred to juice?",options:[{text:"It retains fibre structure and usually supports greater satiety",correct:true,feedback:"Correct. The food matrix changes how it is consumed."},{text:"Juice contains no water",correct:false,feedback:"Juice is largely water."},{text:"Whole fruit contains no carbohydrate",correct:false,feedback:"Whole fruit contains natural carbohydrate."}]}} ,
      {id:"l8-m8",title:"A reusable template beats a perfect menu",highYield:"Design meals with an anchor, energy base, produce and fat/flavour, then secure nutrient-specific sources across the day.",teaching:["A practical meal can be built from four components: a protein-rich anchor; a grain, starchy vegetable or other energy base; vegetables or fruit; and a source of unsaturated fat or flavour. Examples include lentil curry with rice and vegetables, tofu stir-fry with noodles and sesame, or bean tacos with corn, salsa and avocado.","Across the day, verify a reliable B12 source, calcium and vitamin D anchors, an ALA source and a predictable iodine plan. Adapt portions to appetite, life stage and goals. This framework is intentionally flexible: it can organize convenience foods, leftovers, culturally specific dishes and restaurant meals."],keyPoints:["Anchor meals with protein.","Include an adequate energy base.","Add produce and fat/flavour.","Secure B12, calcium/D, ALA and iodine across the day."],visual:{title:"Four-part meal builder",kind:"map",items:[{label:"Anchor",detail:"Beans, lentils, tofu, tempeh, seitan, eggs/dairy if used"},{label:"Energy",detail:"Rice, bread, pasta, potato, corn, oats or other staple"},{label:"Produce",detail:"Vegetable and/or fruit"},{label:"Fat/flavour",detail:"Nuts, seeds, avocado, oil, sauce, herbs and spices"},{label:"Daily safeguards",detail:"B12, calcium/D, ALA and iodine plan"}]},mnemonic:{title:"A-E-P-F",cue:"Anchor · Energy · Produce · Fat/flavour",explanation:"A flexible meal check, not a rigid prescription."},goodToKnow:"A balanced day may include mixed dishes rather than foods separated into visible groups.",practiceConnection:"Start from what the person already eats and improve the missing role rather than replacing the entire cuisine.",activity:{prompt:"A pasta dish has tomato sauce and vegetables but little protein. What is the clearest addition?",options:[{text:"Add lentils, white beans, tofu or another protein anchor",correct:true,feedback:"Correct. The dish already has energy and produce."},{text:"Remove the pasta and serve only lettuce",correct:false,feedback:"That reduces energy without filling the protein gap."},{text:"Add fruit juice as the only change",correct:false,feedback:"Juice does not provide a meaningful protein anchor."}]}}
    ]},
    {id:"restrictive-patterns",title:"Recognize when philosophy becomes nutrition risk",summary:"Understand macrobiotic and other highly restrictive patterns, then strengthen them without caricature or false reassurance.",moments:[
      {id:"l8-m9",title:"Macrobiotic is a philosophy-led pattern, not a synonym for plant based",highYield:"Macrobiotic diets usually emphasize whole grains, vegetables, legumes and traditional foods, but stricter versions may restrict fruit, fats, fluids, fortified foods and reliable supplements enough to create predictable deficiencies.",teaching:["Macrobiotic practice developed from a broader lifestyle philosophy and exists on a spectrum. Common features include a large proportion of whole grains, seasonal vegetables, beans and soy foods, sea vegetables, soups and limited highly processed foods. Some people include small amounts of fish or other animal foods; stricter forms may be fully vegan and may also limit fruit, nuts, seeds, oils, nightshades, beverages or foods judged out of balance. There is no single universal macrobiotic menu.","Whole grains and vegetables can contribute fibre, magnesium and phytochemicals, but philosophical rules do not guarantee nutritional adequacy. Historical studies of strict macrobiotic children reported growth faltering and low energy, protein, vitamin B12, vitamin D, calcium and riboflavin status; iron deficiency also occurred despite seemingly high iron intake. Sea vegetables do not reliably solve B12 or iodine: B12 activity may be absent or misleading, and iodine can range from too little to excessive."],keyPoints:["Macrobiotic patterns vary in strictness and food inclusion.","Whole-food emphasis can coexist with serious nutrient gaps.","Children and pregnancy have less margin for restriction.","Sea vegetables are not precise B12 or iodine solutions."],visual:{title:"Macrobiotic pattern: assets and pressure points",kind:"comparison",items:[{label:"Potential assets",detail:"Whole grains, vegetables, legumes, traditional preparation and low reliance on sugary foods"},{label:"Energy pressure",detail:"Bulky low-fat foods can crowd out calories, especially in children"},{label:"Micronutrient pressure",detail:"B12, D, calcium, iodine, zinc, riboflavin and iron need explicit review"},{label:"Source problem",detail:"Seaweed varies and fermented foods are not dependable B12"},{label:"Life-stage concern",detail:"Pregnancy, lactation, infancy and childhood require qualified oversight"}]},mnemonic:{title:"GRAIN is not the whole plan",cue:"Growth · Reliable B12 · Adequate energy · Iodine · Nutrient diversity",explanation:"Use the cue to respect the pattern while checking its predictable weak points."},goodToKnow:"A dietary philosophy can offer structure, meaning and cultural connection. The nutrition task is to preserve those values while correcting measurable risk.",practiceConnection:"Ask what macrobiotic means in this person's kitchen: exact foods, portions, fats, beverages, supplements and rules. Do not infer strictness from the label alone.",activity:{prompt:"What is the safest interpretation of 'macrobiotic diet'?",options:[{text:"A variable philosophy-led pattern whose actual foods and restrictions must be assessed",correct:true,feedback:"Correct. The label alone does not reveal adequacy or strictness."},{text:"A standard medically complete menu for every life stage",correct:false,feedback:"No single macrobiotic menu guarantees adequacy, especially in vulnerable life stages."},{text:"A guaranteed source of active vitamin B12 because it may include sea vegetables",correct:false,feedback:"Sea vegetables are not dependable active B12 sources."}]}} ,
      {id:"l8-m10",title:"Strengthen restriction with a replacement map",highYield:"Every excluded food role needs an intentional replacement; if many rules remove the replacements too, the plan requires redesign and clinical support.",teaching:["Map foods by function rather than by moral label: protein anchor, energy base, fat, iron/zinc source, calcium/D source, reliable B12, iodine and omega-3. If a pattern removes dairy but uses fortified soy beverage and calcium-set tofu, the calcium role may remain covered. If it also removes fortified foods, supplements, soy, nuts, seeds and oils, several replacement routes disappear at once.","Assess sufficiency at three levels: the day pattern, the repeated week and the person's physiology. A single balanced dinner cannot compensate for consistently inadequate energy; a nutrient table cannot prove absorption; and an adult plan cannot be assumed safe for a growing child. Use growth or weight trajectory, menstrual and GI history, symptoms, medicines and appropriate biomarkers to decide whether diet changes, supplements or referral are needed."],keyPoints:["Name the nutrient role of every major exclusion.","Multiple restrictions can remove all backup routes.","Assess repeated intake, not one ideal day.","Growth, symptoms and biomarkers add evidence beyond a menu."],visual:{title:"Replacement map",kind:"map",items:[{label:"Protein",detail:"Legumes, soy, seitan, nuts/seeds or suitable alternatives"},{label:"Energy and fat",detail:"Adequate grains/starches plus oils, nuts, seeds or avocado"},{label:"Bone",detail:"Fortified calcium/D foods, calcium-set tofu and assessed supplements"},{label:"Blood and thyroid",detail:"Iron strategy, reliable B12 and predictable iodine"},{label:"Follow-up",detail:"Trajectory, symptoms, labs and professional review"}]},mnemonic:{title:"R-E-P-L-A-C-E",cue:"Role · Exclusion · Plan · Label · Assess · Check · Evolve",explanation:"A replacement is complete only when it performs the missing nutrition role in real life."},goodToKnow:"Dietary variety is not a demand to abandon culture. It is a way to build redundancy so one unavailable food does not collapse the whole plan.",practiceConnection:"When a client resists fortification or supplements for philosophical reasons, use shared decision-making: explain the specific physiologic gap, explore acceptable forms, document the risk and coordinate care.",activity:{prompt:"A strict macrobiotic plan excludes animal foods, fortified products, supplements, nuts, seeds and added oils. What is the first nutrition action?",options:[{text:"Map the missing energy, fat and micronutrient roles and redesign with qualified support",correct:true,feedback:"Correct. Multiple replacement pathways have been removed."},{text:"Assume whole grains automatically cover every nutrient",correct:false,feedback:"Whole grains are valuable but do not reliably provide B12, D or complete coverage."},{text:"Add kelp freely for both B12 and iodine",correct:false,feedback:"Kelp is not reliable B12 and may deliver excessive iodine."}]}}
    ]}
  ],
  caseStudy:{title:"The label says vegan, but the pattern is fragile",scenario:"A client eats toast with coconut-based cheese, a salad with no protein, pasta with tomato sauce, and several fruit drinks. Their plant beverage has 1 g protein and no calcium, D or B12. They believe every vegan product is nutritionally equivalent to the food it replaces.",prompts:["Which meal roles are repeatedly missing?","What label comparisons would you demonstrate?","How would you add protein without discarding the client's preferred meals?","Which daily safeguards need a deliberate plan?"],takeaway:"Design from roles and labels, not from product appearance. Small targeted changes can strengthen the whole day without replacing the person's food culture."},
  recap:["Vegetarian describes exclusions, not nutritional adequacy.","Variety across food families creates overlapping nutrient coverage.","A protein anchor should be visible at meals; same-meal complementation is unnecessary.","Regular ALA-rich foods support omega-3 planning.","Plant beverage and alternative-product nutrition varies by label.","Whole fruit and juice are structurally different.","The A-E-P-F meal builder keeps planning flexible.","Macrobiotic diets vary, and strict versions can create energy, protein, B12, D, calcium, iodine, iron, zinc and riboflavin risk.","A replacement map tests whether each exclusion has a practical nutritional substitute.","Reliable B12, calcium/D, iodine and ALA sources should be checked across the day."],
  flashcards:[{front:"Meal anchor",back:"A meaningful protein-rich food that forms the nutritional centre of a meal.",tag:"planning"},{front:"LGVNF",back:"Legumes, grains, vegetables/fruit, nuts/seeds and fortified foods.",tag:"variety"},{front:"Protein complementation",back:"Amino acids from varied plant proteins can complement across the day; exact same-meal pairing is unnecessary for most people.",tag:"protein"},{front:"ALA",back:"The essential plant omega-3 fat found in flax, chia, hemp, walnuts and selected oils.",tag:"fats"},{front:"Algal EPA/DHA",back:"A direct vegetarian long-chain omega-3 source considered according to individual context.",tag:"fats"},{front:"Plant beverage comparison",back:"Check serving, protein, calcium, vitamin D, B12, sugar and intended use.",tag:"labels"},{front:"Fortified nutritional yeast",back:"Provides B12 only when the label confirms fortification.",tag:"labels"},{front:"Plant cheese",back:"A product category with highly variable protein, calcium, saturated fat and sodium.",tag:"labels"},{front:"Whole fruit",back:"Retains fibre structure and usually offers more satiety than juice.",tag:"fruit"},{front:"Fruit drink",back:"May contain little juice and added sugar; it is not automatically a fruit serving.",tag:"fruit"},{front:"A-E-P-F",back:"Anchor, energy base, produce and fat/flavour—the four-part meal builder.",tag:"planning"},{front:"Daily safeguards",back:"Reliable B12, calcium/vitamin D sources, ALA and a predictable iodine plan.",tag:"planning"},{front:"Macrobiotic spectrum",back:"A variable philosophy-led pattern often centred on whole grains, vegetables and legumes; strictness and exclusions differ.",tag:"macrobiotic"},{front:"Macrobiotic pressure points",back:"Energy, protein, B12, D, calcium, iodine, iron, zinc, riboflavin and essential fats require explicit review.",tag:"macrobiotic"},{front:"Replacement map",back:"Match every excluded food role with a reliable, acceptable substitute and verify it in the repeated pattern.",tag:"assessment"}],
  practice:[{prompt:"Why does vegetarian not guarantee a healthy diet?",answer:"It describes excluded foods, not energy adequacy, variety, pattern quality or fortified sources.",rationale:"Assessment must examine what is actually eaten.",tag:"pattern"},{prompt:"List the five LGVNF food roles.",answer:"Legumes, grains, vegetables/fruit, nuts/seeds and fortified foods.",rationale:"The groups provide overlapping coverage.",tag:"variety"},{prompt:"Name three protein anchors.",answer:"Examples include beans, lentils, tofu, tempeh, seitan, soy/pea products, eggs or dairy if used.",rationale:"Meals need a meaningful protein-rich centre.",tag:"protein"},{prompt:"Must beans and grains be eaten in the same meal?",answer:"No. Variety across the day can supply complementary amino acids when energy and protein are adequate.",rationale:"The older same-meal rule is obsolete.",tag:"protein"},{prompt:"Name four ALA sources.",answer:"Ground flax, chia, hemp and walnuts; canola or soybean oil also contribute.",rationale:"Regular ALA foods are the adult foundation.",tag:"fats"},{prompt:"What should be checked on a plant beverage label?",answer:"Serving size, protein, calcium, vitamin D, B12, added sugar and intended use.",rationale:"Products vary widely.",tag:"labels"},{prompt:"Why might plant cheese not replace dairy cheese nutritionally?",answer:"Many products provide little protein or calcium and vary in fat and sodium.",rationale:"Appearance does not establish equivalence.",tag:"labels"},{prompt:"Why is whole fruit generally preferred to juice?",answer:"It retains fibre structure and supports chewing and satiety.",rationale:"Food form changes the eating response.",tag:"fruit"},{prompt:"Build a meal with A-E-P-F.",answer:"Example: tofu anchor, rice energy base, broccoli produce and sesame oil/flavour.",rationale:"The framework is flexible across cuisines.",tag:"planning"},{prompt:"Which nutrient safeguards need a deliberate daily plan?",answer:"At minimum reliable B12, calcium/D sources, ALA and predictable iodine, adjusted to individual needs.",rationale:"These are common vegetarian planning points.",tag:"planning"},{prompt:"Why can a macrobiotic whole-food pattern still be nutritionally inadequate?",answer:"Strict versions can limit energy, fat, fortified foods and reliable sources of B12, D, calcium, iodine and other nutrients.",rationale:"Food philosophy and whole-food emphasis do not guarantee physiologic coverage.",tag:"macrobiotic"},{prompt:"What is the replacement-map question for any exclusion?",answer:"Which nutrient and meal role did the food perform, and what reliable, acceptable food or supplement now performs that role?",rationale:"Replacement by appearance alone can leave the original function uncovered.",tag:"assessment"}],
  sources:[{title:"Academy of Nutrition and Dietetics · Vegetarian Dietary Patterns for Adults (2025)",url:"https://pubmed.ncbi.nlm.nih.gov/39923894/"},{title:"Systematic review · Vegetarian diets during complementary feeding",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC9459879/"},{title:"Health Canada · Applying dietary guidelines to vegetarian diets",url:"https://www.canada.ca/en/health-canada/services/food-guide/explore/dietary-guidelines/applying/considerations-vegetarian-diets.html"}]
};
